from fastapi import FastAPI, HTTPException
from pydantic import BaseModel, Field

app = FastAPI()

class ItemCreate(BaseModel):
    name: str
    price: float = Field(..., gt=0, description="Price must be greater than zero")

class ItemResponse(BaseModel):
    name: str
    total_price: float

@app.post("/items/", response_model=ItemResponse)
def create_item(item: ItemCreate):
    total = round(item.price * 1.15, 2)
    return ItemResponse(name=item.name, total_price=total)

Time Complexity: O(1). Space Complexity: O(1). Edge cases: Pydantic handles negative or zero prices by raising a 422 validation error automatically.

from rest_framework import serializers, status
from rest_framework.response import Response
from rest_framework.views import APIView
from rest_framework.permissions import IsAuthenticated
from .models import Article

class ArticleSerializer(serializers.ModelSerializer):
    class Meta:
        model = Article
        fields = ['id', 'title', 'content', 'author', 'created_at']
        read_only_fields = ['author', 'created_at']

class ArticleCreateView(APIView):
    permission_classes = [IsAuthenticated]

    def post(self, request):
        serializer = ArticleSerializer(data=request.data)
        if serializer.is_valid():
            serializer.save(author=request.user)
            return Response(serializer.data, status=status.HTTP_201_CREATED)
        return Response(serializer.errors, status=status.HTTP_400_BAD_REQUEST)

Time Complexity: O(1). Space Complexity: O(1). Edge cases: Unique title constraints handled by DB/serializer validators.

'use client';

import { useOptimistic, useTransition } from 'react';

export default function LikeButton({ initialLikes, contentId, updateLikeAction }) {
  const [isPending, startTransition] = useTransition();
  const [optimisticLikes, setOptimisticLikes] = useOptimistic(
    initialLikes,
    (currentLikes, updateAmount) => currentLikes + updateAmount
  );

  const handleLike = async () => {
    startTransition(async () => {
      setOptimisticLikes(1);
      try {
        await updateLikeAction(contentId);
      } catch (error) {
        console.error('Failed to update like', error);
      }
    });
  };

  return (
    <button onClick={handleLike} disabled={isPending}>
      ❤️ {optimisticLikes} {isPending ? 'Saving...' : 'Likes'}
    </button>
  );
}

