import heapq

def findKthLargest(nums, k):
    min_heap = []
    for num in nums:
        heapq.heappush(min_heap, num)
        if len(min_heap) > k:
            heapq.heappop(min_heap)
    return min_heap[0]

Time Complexity: O(N log k). Space Complexity: O(k). Edge cases: k equals array length, duplicate elements.

def lengthOfLongestSubstring(s: str) -> int:
    char_map = {}
    max_len = 0
    l = 0
    for r in range(len(s)):
        if s[r] in char_map and char_map[s[r]] >= l:
            l = char_map[s[r]] + 1
        char_map[s[r]] = r
        max_len = max(max_len, r - l + 1)
    return max_len

Time Complexity: O(N). Space Complexity: O(min(N, charset)). Edge cases: Empty string, all identical characters.

